import{_ as t,o,c as a,a0 as s}from"./chunks/framework.1R7PBCUH.js";const m=JSON.parse('{"title":"Exercises 6","description":"","frontmatter":{},"headers":[],"relativePath":"exercises/exercises6.md","filePath":"exercises/exercises6.md"}'),r={name:"exercises/exercises6.md"};function n(i,e,l,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="exercises-6" tabindex="-1">Exercises 6 <a class="header-anchor" href="#exercises-6" aria-label="Permalink to &quot;Exercises 6&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>These exercises are still in draft. The text isn&#39;t polished yet and new exercises may be added in the future.</p></div><h2 id="exercise-6-1" tabindex="-1">Exercise 6.1 <a class="header-anchor" href="#exercise-6-1" aria-label="Permalink to &quot;Exercise 6.1&quot;">​</a></h2><p>Every time you log in using SSH, the server greets you with a welcome message. This message is known as the <strong>message of the day</strong> (<code>motd</code>). In this exercise, you&#39;ll learn to configure this message.</p><p>The message you saw when you first used <code>ssh</code> is configured by various scripts in the <strong>/etc/update-motd.d</strong> directory. Disable these scripts by removing their execute permissions.</p><details><summary>Solution</summary><pre>sudo chmod a-x /etc/update-motd.d/*
</pre></details><p>Configure your own greeting by editing the file <strong>/etc/motd</strong>. Log in using SSH and verify that you can see this greeting.</p><details><summary>Solution</summary><pre>sudo nano /etc/motd
</pre> Then use <code>ssh</code> to connect from your host machine. </details><p>Use <strong><code>figlet</code></strong> to generate a banner that says “Welcome to Ubuntu!”. You&#39;ll have to install this command first, then consult its man page to learn how to use it, how to select a font, and where to find these fonts.</p><p>Pick a font that&#39;s small enough for the text to fit on a single line, and store the resulting banner in <strong>/etc/motd</strong>. This may be trickier than it sounds, so be creative!</p><details><summary>Solution</summary> Install Figlet: <pre>sudo apt install figlet
</pre> Print the font directory and list its contents: <pre>figlet -I 2
ls /usr/share/figlet
</pre> Generate the banner in a small font: <pre>figlet -f small Welcome to Ubuntu! &gt; banner
sudo mv banner /etc/motd
</pre> Output redirect doesn&#39;t work properly with <code>sudo</code>, so save the text in a regular file first, then move it to <strong>/etc/motd</strong>. </details><h2 id="sftp" tabindex="-1">Exercise 6.2 <a class="header-anchor" href="#sftp" aria-label="Permalink to &quot;Exercise 6.2 {#sftp}&quot;">​</a></h2><p>In this exercise, you&#39;ll install and use <a href="https://filezilla-project.org" target="_blank" rel="noreferrer">FileZilla</a>, a popular open source application for remote file transfers.</p><p>Install the free FileZilla Client for your host machine and run the application. Enter the IP address of your virtual machine in the <strong>Host</strong> field, enter your username and password, and connect using port 22.</p><p>FileZilla will use SFTP to connect to the virtual machine and display two file managers: one for your host machine on the left, and one for your virtual machine on the right. Use these file managers to transfer some files between the two machines.</p><h2 id="bandit" tabindex="-1">Exercise 6.3 <a class="header-anchor" href="#bandit" aria-label="Permalink to &quot;Exercise 6.3 {#bandit}&quot;">​</a></h2><p><a href="https://overthewire.org/wargames/" target="_blank" rel="noreferrer">OverTheWire</a> is an online platform that offers free <strong>wargames</strong> to test your skills in Linux, cybersecurity, and reverse engineering. Your goal for this exercise is to play the first game, <a href="https://overthewire.org/wargames/bandit/" target="_blank" rel="noreferrer">Bandit</a>, and complete a few levels.</p><p>You&#39;ll use SSH to connect to Bandit with the username and password for Level 0. In each level, you&#39;ll complete a challenge which will give you the password for the next level. Read the <a href="https://overthewire.org/wargames/bandit/" target="_blank" rel="noreferrer">general instructions</a> before you begin, then start <a href="https://overthewire.org/wargames/bandit/bandit0.html" target="_blank" rel="noreferrer">Level 0</a>.</p><p>Although Bandit claims to be aimed at beginners, the difficulty can vary wildly between levels. Some levels are extremely easy to complete, while others can feel impossibly hard. Many levels also require knowledge that you simply don&#39;t have (yet).</p><p>For this exercise, you&#39;re not expected to be able to complete this game. Even if you only make it to Level 1, that&#39;s fine. At least you had a chance to practice using SSH. If you do want to proceed further, keep the following guidelines in mind:</p><ol><li><p>Be prepared to read. A lot. You&#39;re allowed to consult search engines or AI chatbots during this exercise. However, avoid looking up solutions. Instead, ask questions such as “What does X mean in Bash?”, “What does command X do?”, and “How can I use command X to do Y?”.</p></li><li><p>If you don&#39;t know where to start, every level has a section labeled “Commands you may need to solve this level”. Look up what these commands do and browse their man pages. While many commands listed in this section are decoys, you usually do need at least one of them to solve the challenge.</p></li><li><p>If you get stuck on a level, feel free to skip it by looking up the solution. The game covers a few different topics and you may find a few more easy levels later on in the game. Again, you&#39;re not expected to be able to complete this game yet.</p></li></ol><p>Have fun learning!</p>`,22)])])}const p=t(r,[["render",n]]);export{m as __pageData,p as default};
